<?php

namespace MongoDB\Driver;

use Iterator;
use MongoDB\BSON\Int64;
use MongoDB\Driver\Exception\InvalidArgumentException;

/**
 * <div id="class.mongodb-driver-cursorinterface" class="reference"> <h1 class="title">The MongoDB\Driver\CursorInterface interface</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.6.0)</p>    <div class="section" id="mongodb-driver-cursorinterface.intro">   <h2 class="title">简介</h2>   <p class="simpara">    This interface is implemented by    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span> to be used as    a parameter, return, or property type in userland classes.   </p>  </div>  <div class="section" id="mongodb-driver-cursorinterface.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\CursorInterface</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.iterator.php" class="interfacename">Iterator</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursorinterface.getid.php" class="methodname" style="color:#CC7832">getId</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="type MongoDB\BSON\Int64" style="color:#EAB766">MongoDB\BSON\Int64</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursorinterface.getserver.php" class="methodname" style="color:#CC7832">getServer</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursorinterface.isdead.php" class="methodname" style="color:#CC7832">isDead</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursorinterface.settypemap.php" class="methodname" style="color:#CC7832">setTypeMap</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$typemap</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursorinterface.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 2.0.0</td>       <td>        <span class="simpara">         This interface now extends <span class="interfacename"><a href="https://php.net/manual/zh/class.iterator.php" class="interfacename">Iterator</a></span>.        </span>        <span class="simpara">         Return types previously declared as tentative are now enforced.        </span>       </td>      </tr>             <tr>        <td>PECL mongodb 1.15.0</td>        <td>         在 PHP 8.0 及更高版本中，方法的返回类型被声明为暂定（tentative），         这会导致在实现该接口但未声明相应返回类型的代码中触发弃用提示。         可以添加 <span class="code">#[ReturnTypeWillChange]</span> 属性来消除该弃用提示。        </td>       </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\CursorInterface::getId} — Returns the ID for this cursor</li><li>{@link MongoDB\Driver\CursorInterface::getServer} — Returns the server associated with this cursor</li><li>{@link MongoDB\Driver\CursorInterface::isDead} — Checks if the cursor may have additional results</li><li>{@link MongoDB\Driver\CursorInterface::setTypeMap} — Sets a type map to use for BSON unserialization</li><li>{@link MongoDB\Driver\CursorInterface::toArray} — Returns an array containing all results for this cursor</li></ul></div>
 * 
 * This interface is implemented by MongoDB\Driver\Cursor but may also be used for type-hinting and userland classes.
 * @link https://www.php.net/manual/en/class.mongodb-driver-cursorinterface.php
 * @since 1.6.0
 */
interface CursorInterface extends Iterator
{

    public function current(): array|object|null;

    /**
 * <div id="mongodb-driver-cursorinterface.getid" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\CursorInterface::getId</h1>  <p class="verinfo">(mongodb &gt;=1.6.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\CursorInterface::getId</span> — <span class="dc-title">Returns the ID for this cursor</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursorinterface.getid-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\CursorInterface::getId</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="type MongoDB\BSON\Int64" style="color:#EAB766">MongoDB\BSON\Int64</a></span></div>  <p class="simpara">   Returns the ID for this cursor, which uniquely identifies the cursor on the   server.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursorinterface.getid-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursorinterface.getid-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the ID for this cursor.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursorinterface.getid-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-cursorinterface.getid-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.20.0</td>      <td>       Added <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span> to the tentative return       type for this method. <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursorid.php" class="classname">MongoDB\Driver\CursorId</a></span>       will be removed from the return type in version 2.0.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursorinterface.getid-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Cursor::getId()} - Returns the ID for this cursor</span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursorid.php" class="classname">MongoDB\Driver\CursorId</a></span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span></li>  </ul> </div></div>
 * 
     * Returns the cursor ID associated with this cursor. A cursor ID uniquely identifies the cursor on the server.
     * @return Int64 Returns the cursor ID for this cursor.
     * @throws InvalidArgumentException
     * @link https://www.php.net/manual/en/mongodb-driver-cursorinterface.getid.php
     */
    public function getId(): Int64;

    /**
 * <div id="mongodb-driver-cursorinterface.getserver" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\CursorInterface::getServer</h1>  <p class="verinfo">(mongodb &gt;=1.6.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\CursorInterface::getServer</span> — <span class="dc-title">Returns the server associated with this cursor</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursorinterface.getserver-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\CursorInterface::getServer</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></div>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> associated with this   cursor. This is the server that executed the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-query.php" class="classname">MongoDB\Driver\Query</a></span> or   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-command.php" class="classname">MongoDB\Driver\Command</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursorinterface.getserver-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursorinterface.getserver-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> associated with this   cursor.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursorinterface.getserver-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursorinterface.getserver-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Cursor::getServer()} - Returns the server associated with this cursor</span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span></li>  </ul> </div></div>
 * 
     * Returns the MongoDB\Driver\Server associated with this cursor.
     * This is the server that executed the MongoDB\Driver\Query or MongoDB\Driver\Command.
     * @link https://www.php.net/manual/en/mongodb-driver-cursorinterface.getserver.php
     * @return Server Returns the MongoDB\Driver\Server associated with this cursor.
     * @throws InvalidArgumentException
     */
    public function getServer(): Server;

    /**
 * <div id="mongodb-driver-cursorinterface.isdead" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\CursorInterface::isDead</h1>  <p class="verinfo">(mongodb &gt;=1.6.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\CursorInterface::isDead</span> — <span class="dc-title">Checks if the cursor may have additional results</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursorinterface.isdead-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\CursorInterface::isDead</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">   Checks whether the cursor may have additional results available to read. A   cursor is initially "alive" but may become "dead" for any of the following   reasons:   </p><ul class="simplelist">    <li>Advancing a non-tailable cursor did not return a document</li>    <li>The cursor encountered an error</li>    <li>The cursor read its last batch to completion</li>    <li>The cursor reached its configured limit</li>   </ul>   This is primarily useful with tailable cursors.   </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursorinterface.isdead-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursorinterface.isdead-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if additional results are not available, and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>   otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursorinterface.isdead-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursorinterface.isdead-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Cursor::isDead()} - Checks if the cursor is exhausted or may have additional results</span></li>  </ul> </div></div>
 * 
     * Checks whether the cursor may have additional results available to read.
     * @link https://www.php.net/manual/en/mongodb-driver-cursorinterface.isdead.php
     * @return bool Returns TRUE if additional results are not available, and FALSE otherwise.
     * @throws InvalidArgumentException
     */
    public function isDead(): bool;


    public function key(): ?int;

    /**
 * <div id="mongodb-driver-cursorinterface.settypemap" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\CursorInterface::setTypeMap</h1>  <p class="verinfo">(mongodb &gt;=1.6.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\CursorInterface::setTypeMap</span> — <span class="dc-title">Sets a type map to use for BSON unserialization</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursorinterface.settypemap-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\CursorInterface::setTypeMap</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$typemap</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Sets the <a href="https://php.net/manual/zh/mongodb.persistence.php#mongodb.persistence.typemaps" class="link">type map   configuration</a> to use when unserializing the BSON results into PHP   values.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursorinterface.settypemap-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">typeMap</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>)</dt>    <dd>     <span class="simpara">      <a href="https://php.net/manual/zh/mongodb.persistence.php#mongodb.persistence.typemaps" class="link">Type map configuration</a>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursorinterface.settypemap-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursorinterface.settypemap-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursorinterface.settypemap-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Cursor::setTypeMap()} - Sets a type map to use for BSON unserialization</span></li>   <li><a href="https://php.net/manual/zh/mongodb.persistence.php" class="xref">Persisting Data</a></li>  </ul> </div></div>
 * 
     * Sets a type map to use for BSON unserialization
     * @link https://www.php.net/manual/en/mongodb-driver-cursorinterface.settypemap.php
     * @param array $typemap Type map configuration.
     * @throws InvalidArgumentException
     */
    public function setTypeMap(array $typemap): void;

    /**
 * <div id="mongodb-driver-cursorinterface.toarray" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\CursorInterface::toArray</h1>  <p class="verinfo">(mongodb &gt;=1.6.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\CursorInterface::toArray</span> — <span class="dc-title">Returns an array containing all results for this cursor</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursorinterface.toarray-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\CursorInterface::toArray</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Iterates the cursor and returns its results in an array.   <span class="function">{@link MongoDB\Driver\CursorInterface::setTypeMap()}</span> may be used   to control how documents are unserialized into PHP values.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursorinterface.toarray-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursorinterface.toarray-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> containing all results for this cursor.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursorinterface.toarray-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursorinterface.toarray-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Cursor::toArray()} - Returns an array containing all results for this cursor</span></li>   <li><span class="function">{@link MongoDB\Driver\CursorInterface::setTypeMap()} - Sets a type map to use for BSON unserialization</span></li>  </ul> </div></div>
 * 
     * Iterates the cursor and returns its results in an array.
     * MongoDB\Driver\CursorInterface::setTypeMap() may be used to control how documents are unserialized into PHP values.
     * @return array Returns an array containing all results for this cursor.
     * @throws InvalidArgumentException
     */
    public function toArray(): array;
}
